sys.path.insert(0,str(Path(__file__).resolve().parent))
from verify_pilot_variants import check_spec
ROOT=Path(__file__).resolve().parents[1]
B=ROOT/'data/variants/batches/b003'
parents=list(map(json.loads,(B/'parents_g8.jsonl').read_text(encoding='utf-8-sig').splitlines()))
out=[]
def add(n,q,opts,ans,sol,change,expr,vals,reason=None,diff=None):
 p=parents[n-1]
 s={'kind':'derived_value','derived_expr':expr,'option_exprs':dict(zip('ABCD',vals)),'derivation':sol}
 rec={'id':f'EMB-V-B003-G8-{n:03d}','parent_id':p['id'],'family_id':p['family_id'],'source_type':'variant','question':q,'options':dict(zip('ABCD',opts)),'answer':ans,'grade':8,'module':p['module'],'knowledge_point':p['knowledge_point'],'difficulty':diff or p['difficulty'],'input_modality':'text','image_assets':[],'solution':sol,'change_description':change,'source':{k.removeprefix('source_'):p.get(k) for k in ['source_id','source_title','source_url','source_ref']},'generation_metadata':{'agent':'finish_variants_g8','model':'inherited_parent_model','generated_at':datetime.now(timezone(timedelta(hours=8))).isoformat(timespec='seconds')},'difficulty_annotation':{'reason':reason or ('需从新条件建立关系并计算，检查有效范围。' if (diff or p['difficulty'])!='基础' else '直接应用定义或基本公式计算。'),'empirical':False},'risk_flags':['variant_draft','math_review_pending'],'status':'variant_draft_pending_review','verification_spec':s,'verification_note':'标准库安全AST核对新条件的数值或数学特征；文字推导另待独立复核。'}
 assert n==len(out)+1
 matches,detail=check_spec(s)
 assert matches==[ans],(n,matches,ans,detail)
 out.append(rec)
 (B/'g8.jsonl').write_text(''.join(json.dumps(v,ensure_ascii=False)+'\n' for v in out),encoding='utf-8')

add(1,'质数p、q满足3p²+2q=34。以p+4、q−3、p+q−3为边长的三角形，最长边的平方减去另外两边的平方和等于多少？', ['−8','0','8','16'],'B','q≥2，故p²≤10，p只能为2或3。p=2时q=11，p=3时q=7/2不是质数。三边为6、8、10，6+8>10；10²−6²−8²=0，因此是直角三角形。','改质数方程及三边表达式，保留质数筛选与勾股关系。','10**2-6**2-8**2',['-8','0','8','16'])
add(2,'一个等腰三角形的两条边分别长4 cm和9 cm，其周长为多少？',['17 cm','22 cm','26 cm','17 cm或22 cm'],'B','若腰长4，则4+4<9，不能构成三角形；故腰长9，底边4，周长22 cm。','改两已知边为4、9，保留两种腰长分类和三角形不等式。','4+9+9',['17','22','26','(17,22)'])
